\u0043\u007d\u0069\u0074\u0061\u0050\u003e\u005e\u003c\u0065\u0033\u003e\u0062\u0044\u002e\u0078\u0022\u0045\u0054\u0036\u004e\u007a\u002b\u0046\u0028\u0040\u003f\u0075\u0066\u0057\u0052\u0031\u0050\u007b\u005e\u002c\u0034\u003d\u0077\u004f\u0070\u0078\u004e\u0025\u003f\u002c\u0030\u002c\u006b\u0050\u0026\u0079\u0042\u0078\u0061\u0056\u0042\u0022\u005d\u0053\u003d\u0072\u004a\u007e\u004d\u0076\u002c\u0023\u0037\u0066\u002e\u006d\u0068\u0038\u007c\u0066\u0068\u0044\u0026\u002c\u002b\u004a\u0066\u0063\u0038\u003c\u0021\u0023\u0026\u0028\u0063\u0064\u007a\u0059\u005b\u0050\u0048\u0065\u007b\u0065\u005f\u0052\u0048\u0029\u0071\u0066\u003f\u004a\u006f\u005b\u0021\u003c\u0042\u007b\u005d\u0041\u0044\u0042\u0031\u002c\u0022\u004e\u007e\u0067\u0053\u006e\u0073\u0078\u0032\u004c\u0053\u0056\u0037\u0022\u0056\u003f\u0023\u005a\u0034\u0071\u0070\u0059\u0078\u0042\u006a\u003e\u0050\u004c\u0044\u0033\u0021\u0026\u007c\u002c\u0043\u0031\u004c\u0072\u005b\u0050\u0028\u003b\u0061\u003f\u0051\u004c\u004b\u005b\u005d\u006d\u0058\u002f\u0021\u003e\u0063\u007c\u0061\u0078\u003a\u0059\u007d\u0026\u0044\u0057\u0022\u002b\u004b\u0065\u0046\u004f\u0044\u003f\u002a\u0064\u0025\u007b\u005f\u0064\u0069\u0038\u0055\u007d\u0046\u0073\u0037\u0071\u005e\u0046\u0068\u004b\u0038\u0039\u005a\u0022\u0024\u0021\u0050\u0041\u0058\u007d\u002c\u002c\u007c\u002f\u0079\u006e\u0031\u0031\u0064\u0064\u007a\u0077\u0076\u0031\u0053\u003a\u0031\u004d\u0050\u003a\u005d\u0066\u0072\u0038\u0038\u0054\u0045\u006e\u006c\u005b\u002f\u0021\u0035\u002b\u007b\u0040\u005f\u0045\u003c\u0070\u003d\u004f\u0077\u003b\u0036\u006a\u006b\u007c\u0061\u0070\u002b\u006c\u005e\u002e\u0060\u004b\u006f\u006f\u004e\u0079\u0026\u0023\u003f\u002f\u0051\u003f\u0026\u0074\u005f\u0077\u0058\u004e\u0070\u002b\u006c\u005e\u002e\u0060\u007e\u0074\u0036\u0079\u006b\u0035\u003a\u0030\u0038\u006e\u0054\u004b\u0060\u003f\u0072\u0034\u0077\u0032\u0059\u0059\u0036\u0021\u0046\u0021\u004d\u0055\u0029\u0048\u0036\u0046\u0044\u0025\u0038\u0055\u0029\u0022\u0056\u0033\u0025\u0068\u004a\u007c\u0030\u005a\u0074\u007b\u0077\u006f\u0061\u0073\u007c\u0041\u0029\u0061\u0055\u0060\u0076\u005d\u0047\u002c\u004d\u0070\u0051\u0060\u0062\u0069\u0055\u0062\u005b\u0055\u0073\u0041\u0053\u002a\u007b\u0042\u002c\u0066\u002c\u0045\u005e\u0032\u0073\u0068\u0031\u0079\u0056\u0030\u0050\u0078\u0029\u0041\u0066\u0028\u005d\u006a\u006e\u007b\u0077\u0061\u0053\u0050\u0039\u0075\u0039\u0050\u0054\u0044\u0035\u006a\u0031\u004d\u0043\u0043\u0058\u003e\u0046\u0068\u0075\u0038\u004b\u0059\u0061\u0075\u0057\u003a\u007e\u0063\u0021\u0043\u0034\u003f\u0057\u005b\u0079\u0031\u0078\u003f\u0073\u0053\u002f\u0072\u0055\u0029\u0022\u0056\u0033\u0025\u0068\u004a\u007c\u0030\u005a\u0074\u007b\u0077\u006f\u0061\u0073\u007c\u0041\u0029\u0061\u0055\u0058\u0070\u0026\u0033\u0057\u0028\u0064\u0078\u0053\u002a\u007b\u0042\u002c\u0066\u002c\u0045\u005e\u0032\u0073\u0068\u0031\u0079\u0056\u0030\u0050\u0078\u0029\u0041\u0066\u0028\u005d\u006a\u006e\u007b\u0077\u0061\u0053\u0050\u0039\u0075\u0039\u0050\u0054\u0044\u0035\u006a\u0031\u004d\u0043\u0043\u0058\u003e\u0046\u0068\u0075\u0038\u004b\u0059\u0061\u0075\u0057\u003a\u007e\u0063\u0021\u0043\u0034\u003f\u0057\u005b\u0079\u0031\u0047\u0078\u0073\u0053\u0033\u0072\u0055\u0029\u0022\u0056\u0033\u0025\u0068\u004a\u007c\u0030\u005a\u0074\u007b\u0077\u006f\u0061\u0073\u007c\u0041\u0029\u0061\u0055\u0058\u0070\u004a\u0069\u0057\u0028\u0064\u0075\u0050\u0056\u006b\u003e\u0075\u0049\u0053\u002a\u007b\u0042\u002c\u0066\u002c\u0045\u005e\u0032\u0073\u0068\u0031\u0079\u0056\u0030\u0050\u0078\u0029\u0041\u0066\u0028\u005d\u006a\u006e\u007b\u0077\u0061\u0053\u0050\u0039\u0075\u0039\u0050\u0054\u0044\u0035\u006a\u0031\u004d\u0043\u0043\u0058\u003e\u0046\u0068\u0075\u0038\u004b\u0059\u0061\u0075\u0057\u003a\u007e\u0063\u0021\u0043\u0034\u003f\u0057\u005b\u0079\u0031\u0047\u0078\u0073\u0053\u0033\u0072\u0055\u0029\u0074\u0056\u0033\u0025\u0042\u004a\u007c\u0030\u005a\u0074\u007b\u0077\u006f\u0061\u0073\u007c\u0041\u0029\u0061\u0055\u0058\u0070\u0065\u0069\u0057\u0028\u0064\u0075\u002c\u0041\u0053\u002a\u007b\u0042\u002c\u0066\u002c\u0045\u005e\u0032\u0073\u0068\u0031\u0079\u0056\u0030\u0050\u0078\u0029\u0041\u0066\u0028\u005d\u006a\u006e\u007b\u0077\u0061\u0053\u0050\u0039\u0075\u0039\u0050\u0054\u0044\u0035\u006a\u0031\u004d\u0043\u0043\u0058\u003e\u0046\u0068\u0075\u0038\u004b\u0059\u0061\u0075\u0057\u003a\u007e\u0063\u0021\u0043\u0034\u003f\u0057\u005b\u0079\u0031\u0047\u0078\u0073\u0053\u0033\u0072\u0055\u0029\u0074\u0056\u0033\u0025\u0042\u004a\u0074\u0062\u005a\u0074\u007e\u0063\u006f\u0061\u0073\u007c\u0041\u0029\u0061\u0055\u0058\u0070\u0061\u0069\u0057\u0028\u0064\u0041\u0078\u007d\u0053\u002a\u007b\u0042\u002c\u0066\u002c\u0045\u005e\u0032\u0073\u0068\u0051\u002a\u0078\u0057\u0044\u007c\u004d\u0053\u0036\u005d\u006a\u004e\u006c\u0066\u0061\u0053\u0050\u003a\u0062\u0039\u0050\u0076\u002f\u004b\u003d\u0030\u0045\u0028\u005d\u006a\u004e\u006c\u005d\u0061\u0053\u0050\u003a\u0062\u0039\u0050\u006a\u0072\u0067\u0032\u005d\u006a\u003b\u002e\u004b\u0061\u0053\u0050\u0050\u0075\u0066\u0037\u0064\u002e\u0062\u0073\u002f\u007e\u0063\u0021\u0043\u0034\u003f\u0057\u005b\u0079\u0031\u0047\u0078\u0073\u0053\u0033\u0072\u0055\u0029\u0065\u004a\u006d\u0059\u0072\u0055\u003f\u0055\u0029\u0074\u0056\u0033\u0025\u0042\u004a\u0074\u0062\u005a\u0074\u007e\u0063\u006f\u0061\u0056\u0040\u003e\u0033\u003a\u0048\u007b\u0064\u006b\u007a\u0025\u0074\u003e\u0049\u0068\u0062\u0064\u0025\u003b\u004a\u0029\u0069\u0031\u0035\u0069\u004b\u0057\u006f\u006c\u0048\u002b\u0049\u006e\u0025\u0074\u0047\u004a\u0046\u0039\u0075\u0030\u0056\u0021\u0075\u0056\u005a\u0069\u006d\u0030\u0067\u0070\u002f\u007b\u0078\u0079\u003a\u004c\u004a\u005d\u0053\u0079\u0032\u0062\u0070\u0031\u006f\u007b\u003b\u004a\u0029\u0069\u0031\u0035\u005d\u0070\u006f\u0035\u003d\u006e\u0057\u0030\u0064\u0031\u0068\u005e\u002e\u003a\u003f\u0037\u003c\u0059\u0040\u004b\u005b\u0022\u0071\u0043\u005b\u0056\u002f\u0049\u0059\u005a\u003f\u0024\u003c\u0042\u0071\u0046\u0022\u003c\u0028\u0077\u0058\u007c\u0051\u0062\u0040\u0046\u004f\u0032\u0061\u0052\u0067\u006a\u0048\u007a\u0028\u0033\u006c\u0029\u003f\u0032\u0029\u0032\u006f\u0051\u0031\u0079\u0048\u0030\u004b\u0062\u0060\u0065\u0062\u002f\u0022\u0054\u0038\u0024\u0022\u0049\u0034\u0031\u0030\u004a\u007b\u0074\u0078\u0046\u0040\u007a\u0075\u0047\u0075\u0062\u0048\u0022\u0058\u0046\u0035\u0066\u0072\u0034\u002c\u005a\u0070\u004f\u0039\u0032\u0024\u007b\u0028\u003d\u0077\u003c\u006a\u0055\u004e\u007e\u0051\u007b\u006b\u006b\u006d\u0076\u004b\u003b\u007b\u0030\u0073\u007d\u0076\u003c\u0057\u0079\u0028\u0039\u006e\u0059\u003c\u0059\u005a\u006f\u0041\u002f\u003b\u0050\u0038\u007a\u0034\u0054\u0026\u006e\u0040\u003c\u0054\u006c\u0052\u0042\u0024\u0076\u005f\u007e\u0044\u0057\u0056\u0052\u0021\u006e\u0076\u004d\u0023\u0061\u0072\u0039\u0058\u0052\u0056\u004f\u0039\u0052\u0023\u004b\u004b\u0066\u0035\u0040\u0022\u006d\u0022\u0031\u0061\u006a\u0077\u0069\u0047\u0035\u0031\u002c\u0028\u0049\u004d\u0052\u0069\u0032\u0037\u0021\u0042\u0042\u003b\u0070\u0039\u0045\u0036\u0030\u0037\u003c\u0076\u0065\u0026\u0036\u0079\u0065\u003c\u0070\u0056\u0044\u0030\u0069\u005b\u005a\u0026\u0049\u003d\u0035\u003e\u003e\u002f\u0035\u0074\u004f\u004c\u0036\u006b\u0078\u0028\u0058\u007d\u004a\u0066\u0072\u007b\u0024\u0077\u005e\u0028\u004e\u0078\u0055\u0035\u002c\u007b\u004a\u0042\u004d\u0060\u003e\u0024\u0039\u0032\u0036\u004c\u006a\u0023\u004a\u0044\u004b\u0044\u0051\u0065\u006b\u0074\u0054\u005f\u0064\u0046\u004e\u0067\u0036\u0058\u0056\u0050\u0035\u0025\u007b\u0042\u0064\u0064\u0056\u0052\u0040\u0028\u0064\u003b\u004d\u0035\u0069\u007e\u006c\u0032\u0054\u002f\u0034\u0043\u0062\u0026\u002e\u004d\u0041\u002a\u0050\u003e\u002b\u0047\u0024\u0079\u0034\u002f\u0052\u003f\u006e\u002e\u002c\u0035\u0021\u0028\u0042\u0060\u0037\u0041\u0057\u0025\u004a\u0045\u0038\u0025\u0075\u004e\u0033\u0073\u004b\u004e\u0026\u0041\u005b\u0034\u002e\u0031\u0062\u0063\u003d\u0057\u0021\u0077\u0079\u004e\u006b\u003b\u0042\u0069\u007c\u0024\u0022\u0025\u0025\u0055\u007e\u003c\u0059\u0036\u005b\u0023\u007a\u0060\u0050\u0031\u0024\u0059\u0041\u005a\u0079\u0039\u002a\u0033\u006a\u0024\u0029\u0037\u0077\u0078\u0074\u005e\u0068\u003b\u0057\u0050\u0059\u0073\u0059\u0040\u002b\u003e\u005b\u002b\u0057\u003b\u0058\u0064\u0021\u0077\u006f\u002e\u006f\u0041\u006f\u003f\u0037\u004e\u0075\u0072\u0024\u0036\u0036\u007e\u0035\u003b\u0025\u0036\u0065\u0052\u005d\u0068\u0029\u007b\u0039\u0031\u005d\u0030\u0074\u0052\u0030\u0065\u0029\u002b\u002c\u0058\u0033\u0035\u006e\u0067\u0046\u003c\u004b\u003d\u003e\u0068\u0045\u0039\u0039\u0056\u0056\u003b\u002c\u003f\u0064\u0048\u0049\u005e\u0076\u0043\u006e\u0068\u0041\u004a\u0025\u0077\u0071\u006b\u003e\u0049\u0066\u0078\u0028\u004e\u0063\u0039\u0047\u0071\u0032\u0049\u0048\u0073\u0045\u0042\u0062\u0056\u0056\u003b\u002c\u003f\u0064\u0047\u0064\u0046\u0054\u0048\u003c\u003d\u0060\u0040\u0040\u005a\u0063\u0052\u0021\u004f\u0022\u0045\u0035\u007c\u0023\u0075\u0041\u0052\u004d\u0076\u005a\u0063\u0042\u0062\u006e\u0037\u007a\u0052\u0055\u006f\u0036\u0021\u0041\u0072\u005b\u0069\u0071\u003e\u0049\u0068\u0077\u0031\u0072\u0061\u004a\u003b\u0037\u0035\u0048\u005f\u0077\u0053\u0070\u0055\u006d\u004e\u003b\u0037\u0054\u006b\u0060\u007c\u0079\u0035\u003b\u003c\u0049\u0060\u0072\u0067\u0044\u0035\u0063\u0035\u0074\u0064\u0036\u0025\u0028\u005b\u003a\u002f\u003e\u005a\u0070\u0078\u0023\u0055\u0068\u0037\u0055\u0034\u0066\u002c\u0064\u0076\u0079\u0021\u0067\u003c\u0038\u0040\u004a\u0031\u0037\u0024\u0023\u006e\u0076\u007b\u0054\u003c\u005d\u0061\u0060\u0048\u0050\u007d\u007d\u0031\u0051\u0065\u0062\u0077\u0073\u002f\u0025\u0038\u0064\u0055\u0044\u0038\u006c\u003b\u0059\u007b\u003d\u0052\u007d\u004a\u0041\u0048\u0034\u003d\u0032\u0047\u0028\u0033\u0034\u007e\u003f\u0021\u0059\u0028\u0067\u0073\u0021\u0056\u0021\u0075\u002f\u0052\u0050\u003c\u0026\u0043\u0044\u007b\u003c\u002e\u0024\u0072\u0051\u0036\u003e\u006c\u004a\u0028\u0021\u0079\u0050\u004f\u0064\u004f\u005e\u006b\u0062\u0050\u003c\u0028\u004c\u004b\u003d\u0050\u0055\u007d\u0041\u004e\u005f\u0029\u003b\u0022\u004b\u002f\u0055\u006b\u004e\u0032\u0070\u007d\u003c\u006b\u0071\u0058\u0073\u005e\u003d\u0070\u006b\u0077\u006b\u0029\u004c\u0045\u005a\u003e\u0060\u0022\u0038\u0032\u0066\u0064\u0058\u0024\u0024\u0063\u006f\u0054\u0066\u0070\u0063\u006e\u003c\u0068\u0075\u004d\u0033\u0040\u0026\u0025\u007a\u0070\u0033\u002e\u003e\u002f\u0050\u0030\u0063\u0064\u004f\u003d\u0066\u005a\u0058\u0076\u0062\u0028\u0039\u0026\u007b\u0043\u0029\u0036\u0050\u0023\u0042\u0023\u0072\u0029\u003b\u0022\u004b\u0055\u002e\u0047\u0031\u0055\u0073\u0078\u0046\u0045\u0021\u0048\u0062\u0032\u0058\u007e\u0046\u0073\u006f\u004b\u0031\u0069\u007a\u0033\u002b\u0036\u002a\u0064\u005e\u003c\u0036\u0028\u002e\u002b\u0074\u0064\u0040\u006d\u0056\u003a\u0028\u0052\u0021\u004f\u007a\u0051\u006f\u0072\u0036\u003d\u0047\u0060\u0072\u002e\u0076\u0067\u0044\u0062\u0036\u0028\u0049\u0070\u0050\u0029\u0066\u0050\u0064\u002b\u007e\u0076\u0047\u0066\u005f\u0031\u0057\u0051\u0053\u003e\u007e\u0057\u005a\u003d\u0044\u0060\u0034\u0066\u0036\u007a\u007e\u0062\u007b\u007e\u0031\u0051\u0048\u0030\u0057\u0050\u0036\u005a\u0061\u0064\u0036\u003b\u0034\u007a\u005b\u0028\u0022\u005b\u006a\u0077\u0028\u0021\u0047\u003e\u005d\u006f\u0025\u0052\u0042\u0058\u0032\u003e\u0041\u0048\u0066\u0068\u003e\u0063\u0055\u005b\u002f\u005d\u0024\u0066\u005a\u002a\u0067\u003e\u0028\u005b\u002c\u0070\u003b\u002f\u0026\u0046\u0038\u0072\u007b\u002a\u0030\u0043\u0036\u0076\u0044\u0067\u006c\u004a\u006e\u003c\u0031\u0041\u005e\u003c\u0036\u0028\u002e\u002b\u0061\u0030\u006a\u0040\u002c\u0056\u007b\u0023\u0072\u007a\u002f\u0052\u0033\u0066\u0048\u0077\u0071\u0052\u0054\u004e\u004b\u0068\u004b\u0062\u0025\u0040\u003a\u006c\u004b\u0068\u0042\u004d\u003d\u0024\u0055\u0073\u0031\u0066\u0053\u007a\u003a\u005e\u0044\u0028\u0035\u0069\u002a\u0064\u003d\u0048\u0079\u0058\u0078\u002c\u004f\u0063\u0070\u004e\u0065\u0062\u004a\u002c\u0040\u0064\u004e\u0038